/* ---------- Botón (dentro de la celda del widget) ---------- */
.vt-wrap {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: flex-end;
  box-sizing: border-box; padding: 4px;
}
.vt-btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 10px 18px 10px 12px;
  border: none; border-radius: 999px; cursor: pointer;
  background: #2e5d4b; color: #fff;
  font: 600 15px/1 Roboto, "Helvetica Neue", Arial, sans-serif;
  box-shadow: 0 4px 14px rgba(0, 0, 0, .18);
  transition: transform .15s ease, box-shadow .15s ease, background .15s ease;
  white-space: nowrap;
}
.vt-btn:hover { background: #24493b; transform: translateY(-1px); box-shadow: 0 6px 18px rgba(0, 0, 0, .24); }
.vt-icon { width: 26px; height: 26px; flex: none; }
.vt-icon circle { fill: #34d399; }
.vt-icon path { fill: #11261e; }

