// ===================================================================
//  Widget "Ver vídeo tutorial" para ThingsBoard (tipo: Static widget)
//  Pegar en la pestaña JavaScript del editor de widgets.
// ===================================================================

// ----- CONFIGURACIÓN: edita solo esta parte ------------------------
// Pon aquí la dirección de cada vídeo. Vale cualquiera de estas:
//   - un .mp4 alojado en vuestro servidor:  https://midominio.es/videos/calendario.mp4
//   - YouTube (mejor como "oculto"):         https://youtu.be/XXXXXXXXXXX
//   - Google Drive (compartido con enlace):  https://drive.google.com/file/d/ID/view
//
// QUÉ VÍDEO ABRE CADA WIDGET: se decide por el TÍTULO del widget en el tablero
// (Editar widget > Título; se puede dejar oculto con "Mostrar título" desactivado).
//   - Título "Grupos de riego"  -> abre el vídeo de Grupos de riego
//   - Título "Gemelo digital"   -> abre el vídeo del Gemelo digital
//   - Cualquier otro título     -> abre una ventana con los dos vídeos en pestañas
var VIDEOS = [
    { clave: 'grupos', titulo: 'Grupos de riego: caudales', url: 'https://drive.google.com/file/d/1b3BGZoHYPs_mKteaWd6UGldp3T57c-b5/view?usp=drive_link' },
    { clave: 'gemelo', titulo: 'Gemelo digital de riego',   url: 'https://drive.google.com/file/d/13IOdriNmz1EkPLG17VcQ6R2iZbXi_4T1/view?usp=sharing' }
];
var TEXTO_BOTON = 'Ver vídeo tutorial';
// -------------------------------------------------------------------

var VT_CSS = [
    ".vt-overlay {",
    "  position: fixed; inset: 0; z-index: 100000;",
    "  background: rgba(8, 16, 20, .82);",
    "  display: flex; align-items: center; justify-content: center;",
    "  padding: 24px; box-sizing: border-box;",
    "  opacity: 0; transition: opacity .2s ease;",
    "  font-family: Roboto, \"Helvetica Neue\", Arial, sans-serif;",
    "}",
    ".vt-overlay.vt-open { opacity: 1; }",
    ".vt-modal {",
    "  width: min(1280px, 100%);",
    "  background: #0f1d23; border-radius: 14px; overflow: hidden;",
    "  box-shadow: 0 24px 60px rgba(0, 0, 0, .5);",
    "  transform: scale(.97); transition: transform .2s ease;",
    "}",
    ".vt-overlay.vt-open .vt-modal { transform: scale(1); }",
    ".vt-head {",
    "  display: flex; align-items: center; justify-content: space-between;",
    "  gap: 12px; padding: 10px 10px 10px 14px; background: #0b161b;",
    "}",
    ".vt-tabs { display: flex; gap: 6px; flex-wrap: wrap; }",
    ".vt-tab {",
    "  border: none; background: transparent; color: #b8c9c3;",
    "  font-size: 15px; font-weight: 500; line-height: 1; font-family: inherit;",
    "  padding: 9px 14px; border-radius: 8px; cursor: pointer;",
    "}",
    ".vt-tab:hover { background: rgba(255, 255, 255, .06); color: #fff; }",
    ".vt-tab.vt-active { background: #2e5d4b; color: #fff; }",
    ".vt-tab.vt-solo { cursor: default; background: transparent; color: #fff; font-weight: 600; }",
    ".vt-close {",
    "  border: none; background: transparent; color: #cfdcd7;",
    "  font-size: 30px; line-height: 1; width: 40px; height: 40px;",
    "  border-radius: 8px; cursor: pointer;",
    "}",
    ".vt-close:hover { background: rgba(255, 255, 255, .08); color: #fff; }",
    ".vt-player {",
    "  position: relative; width: 100%;",
    "  aspect-ratio: 16 / 9; max-height: calc(100vh - 120px);",
    "  background: #000;",
    "}",
    ".vt-player video, .vt-player iframe {",
    "  position: absolute; inset: 0; width: 100%; height: 100%; border: 0; background: #000;",
    "}",
    ".vt-error { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 32px; text-align: center; color: #e6eeeb; font-size: 17px; }",
    ".vt-error b { font-size: 22px; color: #fff; }",
    ".vt-error code { background: rgba(255,255,255,.08); padding: 8px 12px; border-radius: 6px; font-size: 14px; word-break: break-all; color: #ffd27a; }",
].join('\n');

self.onInit = function () {
    // Permite sobrescribir la configuración desde los ajustes del widget (opcional)
    var s = (self.ctx && self.ctx.settings) || {};
    if (Array.isArray(s.videos) && s.videos.length) VIDEOS = s.videos;
    if (s.textoBoton) TEXTO_BOTON = s.textoBoton;

    // Elegir el vídeo según el título del widget
    var titulo = normalizar((self.ctx.widgetConfig && self.ctx.widgetConfig.title) || '');
    var elegidos = VIDEOS.filter(function (v) { return v.clave && titulo.indexOf(normalizar(v.clave)) !== -1; });
    if (elegidos.length) VIDEOS = elegidos;

    // Estilos de la ventana grande (van al <head> porque la ventana vive fuera de la celda)
    if (!document.getElementById('vt-global-style')) {
        var st = document.createElement('style');
        st.id = 'vt-global-style';
        st.textContent = VT_CSS;
        document.head.appendChild(st);
    }

    var root = self.ctx.$container[0];
    var btn = root.querySelector('.vt-btn');
    root.querySelector('.vt-btn-text').textContent = TEXTO_BOTON;
    btn.addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        abrirModal(0);
    });
};

function normalizar(t) {
    return String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function urlEmbebida(url) {
    var m = url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{11})/);
    if (m) return { tipo: 'iframe', src: 'https://www.youtube-nocookie.com/embed/' + m[1] + '?autoplay=1&rel=0' };
    m = url.match(/drive\.google\.com\/file\/d\/([\w-]+)/);
    if (m) return { tipo: 'iframe', src: 'https://drive.google.com/file/d/' + m[1] + '/preview' };
    m = url.match(/vimeo\.com\/(\d+)/);
    if (m) return { tipo: 'iframe', src: 'https://player.vimeo.com/video/' + m[1] + '?autoplay=1' };
    return { tipo: 'video', src: url };
}

function abrirModal(indice) {
    cerrarModal();
    var ov = document.createElement('div');
    ov.className = 'vt-overlay';
    ov.innerHTML =
        '<div class="vt-modal" role="dialog" aria-modal="true">' +
        '  <div class="vt-head">' +
        '    <div class="vt-tabs"></div>' +
        '    <button class="vt-close" aria-label="Cerrar">&times;</button>' +
        '  </div>' +
        '  <div class="vt-player"></div>' +
        '</div>';
    // Se añade al body para que ocupe toda la pantalla, no solo la celda del widget
    document.body.appendChild(ov);
    self._overlay = ov;

    var tabs = ov.querySelector('.vt-tabs');
    VIDEOS.forEach(function (v, i) {
        var t = document.createElement(VIDEOS.length > 1 ? 'button' : 'span');
        t.className = 'vt-tab' + (VIDEOS.length === 1 ? ' vt-solo' : '');
        t.textContent = v.titulo;
        if (VIDEOS.length > 1) t.addEventListener('click', function () { mostrar(i); });
        tabs.appendChild(t);
    });

    ov.querySelector('.vt-close').addEventListener('click', cerrarModal);
    ov.addEventListener('click', function (e) { if (e.target === ov) cerrarModal(); });
    self._onKey = function (e) { if (e.key === 'Escape') cerrarModal(); };
    document.addEventListener('keydown', self._onKey);

    mostrar(indice);
    requestAnimationFrame(function () { ov.classList.add('vt-open'); });
}

function mostrar(i) {
    var ov = self._overlay; if (!ov) return;
    var player = ov.querySelector('.vt-player');
    player.innerHTML = '';
    var e = urlEmbebida(VIDEOS[i].url);
    var el;
    if (e.tipo === 'iframe') {
        el = document.createElement('iframe');
        el.src = e.src;
        el.allow = 'autoplay; fullscreen; picture-in-picture';
        el.allowFullscreen = true;
    } else {
        el = document.createElement('video');
        el.src = e.src; el.controls = true; el.autoplay = true; el.playsInline = true;
        el.addEventListener('error', function () { avisoError(player, VIDEOS[i].url); });
    }
    player.appendChild(el);
    ov.querySelectorAll('.vt-tab').forEach(function (t, k) { t.classList.toggle('vt-active', k === i); });
}

function avisoError(player, url) {
    var d = document.createElement('div');
    d.className = 'vt-error';
    d.innerHTML = '<b>No se ha podido cargar el vídeo.</b>' +
        '<span>Revisa que la dirección sea la del archivo .mp4 (o un enlace de YouTube o Google Drive) y que no pida iniciar sesión.</span>' +
        '<code></code>';
    d.querySelector('code').textContent = url;
    player.innerHTML = ''; player.appendChild(d);
}

function cerrarModal() {
    if (self._overlay) {
        var v = self._overlay.querySelector('video'); if (v) v.pause();
        self._overlay.remove(); self._overlay = null;
    }
    if (self._onKey) { document.removeEventListener('keydown', self._onKey); self._onKey = null; }
}

self.onResize = function () {};
self.onDestroy = function () { cerrarModal(); };

